import React, { useState, useEffect, useRef } from 'react';
import './LazyImage.css';
import performanceMonitor from '../../utils/performanceMonitor';

const LazyImage = ({ 
  src, 
  alt, 
  className = '', 
  placeholder = null,
  fallback = null,
  priority = false,
  onLoad = null,
  onError = null,
  ...props 
}) => {
  const [imageStatus, setImageStatus] = useState('loading');
  const [currentSrc, setCurrentSrc] = useState(placeholder || src);
  const imgRef = useRef(null);
  const observerRef = useRef(null);

  useEffect(() => {
    if (priority) {
      // Load immediately if priority
      loadImage();
    } else {
      // Use Intersection Observer for lazy loading
      setupIntersectionObserver();
    }

    return () => {
      if (observerRef.current) {
        observerRef.current.disconnect();
      }
    };
  }, [src, priority]);

  const setupIntersectionObserver = () => {
    if ('IntersectionObserver' in window) {
      observerRef.current = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              loadImage();
              observerRef.current.disconnect();
            }
          });
        },
        {
          rootMargin: '50px', // Start loading 50px before image comes into view
          threshold: 0.01
        }
      );

      if (imgRef.current) {
        observerRef.current.observe(imgRef.current);
      }
    } else {
      // Fallback for browsers without Intersection Observer
      loadImage();
    }
  };

  const loadImage = () => {
    if (!src) {
      setImageStatus('error');
      return;
    }

    // Start performance monitoring
    performanceMonitor.startImageLoad(src);

    const img = new Image();

    img.onload = () => {
      setCurrentSrc(src);
      setImageStatus('loaded');

      // End performance monitoring
      performanceMonitor.endImageLoad(src);

      if (onLoad) onLoad(src);
    };

    img.onerror = () => {
      setImageStatus('error');

      // End performance monitoring even on error
      performanceMonitor.endImageLoad(src);

      if (fallback) {
        setCurrentSrc(fallback);
        setImageStatus('loaded');
      }
      if (onError) onError(src);
    };

    img.src = src;
  };

  const getImageClasses = () => {
    const baseClasses = ['lazy-image'];
    if (className) baseClasses.push(className);
    if (imageStatus === 'loading') baseClasses.push('loading');
    if (imageStatus === 'loaded') baseClasses.push('loaded');
    if (imageStatus === 'error') baseClasses.push('error');
    return baseClasses.join(' ');
  };

  return (
    <div className="lazy-image-container">
      <img
        ref={imgRef}
        src={currentSrc}
        alt={alt}
        className={getImageClasses()}
        {...props}
      />

      {imageStatus === 'loading' && (
        <div className="image-placeholder">
          <div className="loading-spinner"></div>
        </div>
      )}

      {imageStatus === 'error' && !fallback && (
        <div className="image-error">
          <div className="error-icon">⚠️</div>
          <span>Failed to load image</span>
        </div>
      )}
    </div>
  );
};

export default LazyImage;
